#!/usr/bin/env bash
# Publishes the GitHub release vVERSION (`make release VERSION=X.Y.Z`):
#
#   1. checks: semver VERSION, gh logged in, clean working tree on the
#      default branch, in sync with origin, both crate versions (and the
#      dir-24-8-derive requirement) equal to VERSION, tag and release unused;
#   2. `make ci` (CHECKS=0 skips it);
#   3. `cargo package` of both crates, attached to the release;
#   4. annotated tag vVERSION, pushed to origin;
#   5. `gh release create`, notes generated by GitHub (NOTES=<file> instead).
#
# The pushed tag also triggers .github/workflows/pages.yml, which rebuilds
# the GitHub Pages site with fresh benchmark reports.
#
# DRY_RUN=1 runs the checks and prints the publishing commands instead of
# running them. DRAFT=1 creates a draft. A version with a pre-release part
# (1.0.0-rc.1) is published as a pre-release.
set -euo pipefail

version=${VERSION:-}
dry_run=${DRY_RUN:-0}
die() {
  printf 'release: %s\n' "$*" >&2
  exit 1
}
step() { printf '\n==> %s\n' "$*"; }
# Publishing commands: printed instead of run with DRY_RUN=1.
publish() {
  if [[ $dry_run == 1 ]]; then
    printf 'dry run:'
    printf ' %q' "$@"
    printf '\n'
  else
    "$@"
  fi
}

semver='^[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.-]+)?(\+[0-9A-Za-z.-]+)?$'
[[ $version =~ $semver ]] || die "VERSION=X.Y.Z required (semver), got '$version'"
tag="v$version"
cd "$(git rev-parse --show-toplevel)"

step "checks for $tag"
command -v gh >/dev/null || die "gh (GitHub CLI) is not installed"
command -v jq >/dev/null || die "jq is not installed"
gh auth status >/dev/null 2>&1 || die "gh is not logged in: run gh auth login"
git remote get-url origin >/dev/null 2>&1 || die "no origin remote"
repo=$(gh repo view --json nameWithOwner -q .nameWithOwner) ||
  die "cannot find the GitHub repository of origin"
default=$(gh repo view --json defaultBranchRef -q .defaultBranchRef.name)
[[ -n $default ]] || die "$repo has no default branch yet: push it first"

[[ -z $(git status --porcelain) ]] || die "the working tree has uncommitted or untracked changes"
branch=$(git symbolic-ref --quiet --short HEAD) || die "detached HEAD"
[[ $branch == "$default" ]] || die "on branch $branch: releases are made from $default"
git fetch --quiet --tags origin "$default"
[[ $(git rev-parse HEAD) == $(git rev-parse "origin/$default") ]] ||
  die "$default and origin/$default differ: push or pull first"

versions=$(cargo metadata --no-deps --format-version 1 | jq -r --arg v "$version" '
  .packages[] | select(.name == "dir-24-8" or .name == "dir-24-8-derive")
  | (select(.version != $v) | "\(.name) is \(.version)"),
    (.dependencies[] | select(.name == "dir-24-8-derive" and .req != "^\($v)")
     | "the dir-24-8-derive requirement is \(.req)")')
[[ -z $versions ]] || die "versions differ from $version: $(echo "$versions" | paste -sd ';' -)
  set version = \"$version\" in Cargo.toml and derive/Cargo.toml (and the dir-24-8-derive
  dependency), commit and push, then run make release VERSION=$version again"

git rev-parse --quiet --verify "refs/tags/$tag" >/dev/null && die "tag $tag already exists locally"
[[ -z $(git ls-remote --tags origin "refs/tags/$tag") ]] || die "tag $tag already exists on origin"
gh release view "$tag" --repo "$repo" >/dev/null 2>&1 && die "release $tag already exists on $repo"
echo "ok: $repo, $default at $(git rev-parse --short HEAD), crates at $version"

if [[ ${CHECKS:-1} == 0 ]]; then
  step "make ci skipped (CHECKS=0)"
else
  step "make ci"
  make ci
fi

step "packages"
cargo package -p dir-24-8-derive -p dir-24-8 --no-verify --quiet
assets=("target/package/dir-24-8-$version.crate" "target/package/dir-24-8-derive-$version.crate")
ls -l "${assets[@]}"

step "tag $tag"
publish git tag -a "$tag" -m "dir-24-8 $version"
publish git push origin "refs/tags/$tag"

step "GitHub release $tag"
args=(--repo "$repo" --title "$tag" --verify-tag)
if [[ -n ${NOTES:-} ]]; then
  [[ -f $NOTES ]] || die "NOTES file $NOTES not found"
  args+=(--notes-file "$NOTES")
else
  args+=(--generate-notes)
fi
[[ ${DRAFT:-0} == 1 ]] && args+=(--draft)
[[ $version == *-* ]] && args+=(--prerelease)
publish gh release create "$tag" "${args[@]}" "${assets[@]}"

if [[ $dry_run == 1 ]]; then
  step "dry run: nothing was tagged, pushed or published"
else
  step "published: $(gh release view "$tag" --repo "$repo" --json url -q .url)"
fi
